import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const D=JSON.parse('{"title":"2017-JUN-07 :: Ceph Developer Monthly","description":"","frontmatter":{"title":"2017-JUN-07 :: Ceph Developer Monthly","date":"2017-06-22T00:00:00.000Z","updated":"2017-06-22T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可扩展性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-JUN-07_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2017/2017-JUN-07_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780459816000}'),p={name:"posts/2017/2017-JUN-07_-_-_Ceph_Developer_Monthly.md"};function r(s,l,_,n,a,u){return t(),i("div",null,[...l[0]||(l[0]=[o("<p>在2017年6月的Ceph开发者月度会议上，社区开发者和相关人员讨论了多个与Ceph分布式存储相关的议题，包括RBD持久缓存、存储池标签、系统D、SethOSD和BlueStore元数据等。以下是对会议内容的详细总结：</p><p><strong>一、RBD持久缓存更新</strong></p><ul><li>会议讨论了基于Jason草图的RBD持久缓存更新，该缓存框架通过boss进行处理，包含日志存储、缓存事件存储和元存储。</li><li>当前性能表现不佳，IOPS下降。</li><li>下一步计划包括优化缓存策略、支持unicast和scatter-gather功能，以及学习更多内存缓存模块。</li></ul><p><strong>二、存储池标签元数据</strong></p><ul><li>会议讨论了为存储池添加标签功能，以提高存储池的可识别性和易用性。</li><li>讨论了是否使用“应用”标签，还是使用更通用的元数据映射，以及是否强制要求标签等问题。</li><li>结论为添加“应用”标签和元数据映射，但不强制要求，并提供健康警告。</li></ul><p><strong>三、系统D改进</strong></p><ul><li>讨论了简化集群部署和配置的改进措施。</li><li>系统D对自定义集群名称的支持不完整，且存在兼容性问题。</li><li>结论为移除系统D对自定义集群名称的支持，并使用升级路径处理兼容性问题。</li></ul><p><strong>四、集群默认工具</strong></p><ul><li>讨论了集群创建时默认安装的工具过多，且部分工具未启用SSO的问题。</li><li>结论为移除默认安装的工具，并对SSO进行改进。</li></ul><p><strong>五、SethOSD部署工具</strong></p><ul><li>讨论了简化OSD部署和配置的问题。</li><li>SethOSD部署工具过于复杂，且对LVM支持不完整。</li><li>结论为使用LVM作为部署工具，并简化部署流程。</li></ul><p><strong>六、BlueStore元数据</strong></p><ul><li>讨论了BlueStore元数据过多，导致性能下降的问题。</li><li>结论为尝试使用LMDB作为元数据存储后端，并继续研究优化元数据存储的方法。</li></ul><p><strong>后续行动计划</strong></p><ul><li>完成RBD持久缓存优化。</li><li>实现存储池标签功能。</li><li>移除系统D对自定义集群名称的支持。</li><li>简化SethOSD部署工具。</li><li>尝试使用LMDB作为元数据存储后端。</li></ul><p>本次会议讨论了多个Ceph相关议题，并制定了后续行动计划，以进一步改进Ceph的性能和易用性。</p>",16)])])}const S=e(p,[["render",r]]);export{D as __pageData,S as default};
